# Codepoint escape are not reused during parsing

SELECT ?v {
  VALUES ?v {
    "abc\u005Cdef"
    "abc\u005Ctuv"
    "\u005CA"
    "\\u005C"
    "\u005C\u005C"
    "\\\u005C"
    "\\\\"
    "\u005Cn"
  }
}

PREFIX ex: <http://example.org/>
SELECT * WHERE {
  ?s ex:p ( "a"@en--ltr ex:b "c"@en ex:d <<( ex:e ex:f ex:g )>> ex:h << ex:i ex:j ex:k >> ex:l ) .
}

PREFIX : <http://example.com/ns#>

CONSTRUCT {
  ?t :graph ?g .
} WHERE {
  GRAPH ?g {
    ?s ?p ?o .
    BIND(<<(?s ?p  ?o)>> AS ?t)
  }
}
